/* ========== 难度档位 ========== */
const DIFFS = [
  /* patch54：fort = 机遇值档位（1..4），决定「每一年会发生几件事」的总概率带。
     它属于难度参数，界面不显示、不参与属性判定，玩家只能从人生密度上感觉到。
     v0.0.3：pos = 本难度「正面事件 : 负面事件」的目标占比（正面占比）。
     它同时约束本地池抽取与 AI 生成指令，保证越简单的档位一生越不那么苦：
       d0 新手档 3:1（0.75）· d1 进阶档 2.5:1（≈0.714）
       d2 硬核档 1.5:1（0.6） · d3 地狱档 1:1（0.5）
     negDamp = 负面效果衰减：越简单的档位，坏事打在属性上越轻。 */
  {id:'d0', n:'新手档', pts:52, cap:20, d:'点数充裕，一生平缓', rare:0.5, need:0, fort:1, pos:0.75, pn:'3:1',   negDamp:0.55},
  {id:'d1', n:'进阶档', pts:42, cap:25, d:'标准体验，起伏适中', rare:1.0, need:0, fort:2, pos:0.714, pn:'2.5:1', negDamp:0.7},
  {id:'d2', n:'硬核档', pts:36, cap:30, d:'点数偏紧，诸事缠身', rare:2.0, need:1, fort:3, pos:0.6,   pn:'1.5:1', negDamp:0.85},
  {id:'d3', n:'地狱档', pts:30, cap:36, d:'极限开局，一生跌宕', rare:3.0, need:3, fort:4, pos:0.5,   pn:'1:1',   negDamp:1.0}
];
/* 分段消耗：1-10 每点 1；11-20 每点 2；21-30 每点 3；31-40 每点 4；41+ 每点 5 */
function costOf(cur){ return cur < 10 ? 1 : cur < 20 ? 2 : cur < 30 ? 3 : cur < 40 ? 4 : 5; }
/* 突破被动 */
