/* 【性能：阶段源池缓存】
   dbPool 在「每个事件」都要调一次，而它只用到某一个阶段的事件。
   以前每次都走 dataOf('ev') —— 那是把全库 4605 条重新浅拷贝一遍，
   为了取其中 400 条，白扔了 2000 条的拷贝开销。
   这里按阶段缓存「源对象数组」，dbPool 只在它上面做过滤 + 投影。
   安全性：缓存的是 dataOf('ev') 独立产生的一份结果，且 dbPool 对源对象
   只读（它 map 出的是全新的 row 对象），不会污染缓存。
   失效时机：内容库写入（dbxSet）—— 见 dataOf 那边调用的 evDeriveClear 一并清。 */
let _stageSrc = {};
function stageSrcClear(){ _stageSrc = {}; }
function stageSrc(stage){
  let a = _stageSrc[stage];
  if(!a){
    a = dataOf('ev').filter(x => x && x.stage === stage);
    _stageSrc[stage] = a;
  }
  return a;
}
function dbPool(stage){
  // 走统一内容库（内置 + 覆盖层），事件字段已规范化为 stage/age/weight/text/effects
  /* 需求 27：性别过滤 —— 「通用」事件人人可遇，专属事件只给对应性别。
     角色没定性别时（老存档 / 测试）按通用处理，等价于不过滤。
     注意：x.sex 已由 dataOf 的 evDerive 缓存算好，这里直接读，不再重复跑语义判定。 */
  const me = (S && S.sex) || '通用';
  const list = stageSrc(stage)
    .filter(x => { const sx = x.sex || evSex(x); return sx === '通用' || sx === me; });
  if(!list.length) return null;
  const rows = list.map(r => ({t:r.text, e:r.effects || {}, w:r.weight || 5,
    lo:r.age[0], hi:r.age[1], id:r.id, tags:(r.tags || []).slice(),
    aff:(r.aff && r.aff.length) ? r.aff.slice() : null,
    /* 需求 27：性别编号（隐藏）—— 池子已按性别过滤过，这里透传是为了同签名随机去重 */
    sex: r.sex || evSex(r),
    /* patch54：需求向量 / 子项增量 / 峰值年龄 / 一生一次 —— 全部可选 */
    req: r.req || null, subs: r.subs || null,
    peak: (r.peak == null ? null : r.peak), once: !!r.once}));
  /* 已经拥有该标签的事件不再重复出现 —— 不然会出现「又解锁了一次房贷」这种重复感。
     现成标签事件全是 patch43 新加的（老库里 tags 一律为空），所以旧行为不受影响。 */
  if(S && Array.isArray(S.tags) && S.tags.length){
    const have = S.tags;
    const filtered = rows.filter(r => !(r.tags && r.tags.length &&
      r.tags.every(t => have.indexOf(t) >= 0)));
    if(filtered.length) return filtered;
  }
  return rows;
}
/* 年龄 -> 数据库阶段名 */
function dbStageOf(a){
  if(a <= 3) return '幼年';
  if(a <= 12) return '童年';
  if(a <= 18) return '少年';
  if(a <= 30) return '青年';
  if(a <= 60) return '中年';
  return '老年';
}
/* ===== 需求 28：同款随机去重 =====
   「性别编号 + 属性数值」完全相同的条目视为同一款（换词不换事）。
   抽到时不在它们之间比权重，而是随机取一条 —— 避免同款桥段反复出现。
   签名只取性别、effects、aff 三项，不含文案本身。 */
function evSign(x){
  if(!x) return '';
  const e = x.e || x.effects || {};
  const ks = Object.keys(e).sort();
  let h = String(x.sex || '通用') + '|';
  ks.forEach(k => { h += k + ':' + (Number(e[k]) || 0) + ','; });
  h += '|' + (x.aff ? [].concat(x.aff).slice().sort().join('') : '');
  return h;
}
/* 在同签名的候选里随机取一条：优先还没出现过的，都出现过了才回落到全体 */
function sigPick(x, pool){
  if(!x || !pool || pool.length < 2) return x;
  const s = evSign(x);
  const same = pool.filter(y => evSign(y) === s);
  if(same.length < 2) return x;
  const fresh = same.filter(y => !evStamp[y.t]);
  const cand = fresh.length ? fresh : same;
  return cand[Math.floor(Math.random() * cand.length)];
}
/* 本局每个事件「最后一次出现」的全局序号；没出现过的记为 0 */
let evStamp = {};
let evTick = 0;
/* 最近若干年刚出现过的文案：保证相邻年份绝不重样 */
let evRecent = [];
const EV_RECENT_WIN = 8;
/* 需求 D：AI 自己写过的文案窗口 —— 让 AI 能看到前几年写过什么，
   否则它每次请求都是「失忆」状态，写出来的年度事件各说各话 */
let aiRecent = [];
const AI_RECENT_WIN = 6;
/* 阶段划分与文本数据库完全一致（6 段）：
   幼年 0-3 / 童年 4-12 / 少年 13-18 / 青年 19-30 / 中年 31-60 / 老年 61+ */
const stageOf = a => a <= 3 ? '幼年' : a <= 12 ? '童年' : a <= 18 ? '少年'
  : a <= 30 ? '青年' : a <= 60 ? '中年' : '老年';
const STAGES = ['幼年', '童年', '少年', '青年', '中年', '老年'];
const STAGE_RANGE = { '幼年':[0,3], '童年':[4,12], '少年':[13,18], '青年':[19,30], '中年':[31,60], '老年':[61,200] };
function markEv(t){
  evTick++;                      // 全局递增序号，标记「最后一次出现在第几年」
  evStamp[t] = evTick;
  evRecent.push(t);
  if(evRecent.length > EV_RECENT_WIN) evRecent.shift();
}
/* 在候选里挑「离现在最久」的那条。 */
function lruPick(pool){
  let best = pool[0], bs = 1e9;
  pool.forEach(x => {
    const s = evStamp[x.t] || 0;   // 0 = 本局还没出现过，最久远
    if(s < bs){ bs = s; best = x; }
  });
  return best;
}
/* 按权重抽一条（权重越高越常见），配合去重使用 */
function weightedPick(pool){
  let sum = 0;
  pool.forEach(x => { sum += (x.w || 5); });
  let r = Math.random() * sum;
  for(let i = 0; i < pool.length; i++){
    r -= (pool[i].w || 5);
    if(r <= 0) return pool[i];
  }
  return pool[pool.length - 1];
}
/* ---------------------------------------------------------
   本地事件抽取：严格按「阶段」取池，绝不跨阶段串插。
   阶段划分与文本数据库一致：幼年0-3 / 童年4-12 / 少年13-18 /
   青年19-30 / 中年31-60 / 老年61+
   阶段内再分两层：
     ① 先挑「自带区间包含当前岁数」的条目（24 岁不会写「考上大学」）
     ② 该层实在挑不出新的，才放宽到整个阶段
   每层内部：本局没出现过的 → 近 8 年没出现过的 → 最久远的一条。
   --------------------------------------------------------- */
/* 从池子里挑「尽量没出现过」的一条：本局没出现 > 近 8 年没出现 > 最久远 */
function pickFresh(pool){
  if(!pool || !pool.length) return null;
  let c = pool.filter(x => !evStamp[x.t]);
  if(c.length) return weightedPickAff(c);
  c = pool.filter(x => evRecent.indexOf(x.t) < 0);
  if(c.length) return weightedPickAff(c);
  return lruPick(pool);
}
/* 严格版抽取：只在「本局没出现过」的候选里挑，一个都挑不到就返回 null。
   属性专属通道用它 —— 同一个属性事件在一局里出现两次，玩家一眼就能看出是模板复用。 */
function pickNew(pool){
  if(!pool || !pool.length) return null;
  const c = pool.filter(x => !evStamp[x.t]);
  if(!c.length) return null;
  return weightedPickAff(c);
}
/* ---------- patch43 需求 1：临终症状池 ----------
   剩余寿命 ≤ DYING_YEARS 年时启用。让死亡有征兆：最后几年先出现身体信号，
   而不是某一年毫无铺垫地直接「归零」。 */
const DYING_YEARS = 4;
const DYING_RATE = 0.7;      // 临终窗口内 70% 走症状池，留 30% 过日常，避免每年都是病
const DYING_FORCE = 2;       // 剩余 ≤2 年时无视概率，必定出症状（死亡铺垫不可缺）
function dyingPool(stage, age){
  const rows = DB_DYING_EV[stage] || [];
  const out = [];
  rows.forEach((r, i) => {
    if(r[0] > age || r[1] < age) return;
    out.push({t: r[3], e: r[4] || {}, w: r[2], lo: r[0], hi: r[1],
              id: 'dy' + stage + i, tags: [], aff: null, dying: true});
  });
  return out;
}
/* 剩余寿命（年）：寿命上限 - 当前年龄。
   无敌模式不再特判 —— 它现在同样活到 200 岁，临终通道理应照常生效，
   否则 196~200 岁这几年会缺掉本该有的身体征兆铺垫。 */
function yearsLeft(){
  if(!S) return 99;
  return (Number(S.lifespan) || LIFE_BASE) - (Number(S.age) || 0);
}
/* ---------- patch43 需求 2：属性专属事件池 ----------
   达到门槛的属性会解锁自己的专属事件线，事件的 aff 字段直接标出它偏向哪个属性。
   这样「高智力」的人生会真的长出智力线，「体质薄弱」也真的会反复受挫。 */
const ATTR_EV_RATE = 0.3;    // 普通年份里 30% 优先尝试属性专属事件
function attrPool(stage, age){
  const a = (S && S.attr) || {};
  const out = [];
  DB_ATTR_EV.forEach((g, gi) => {
    const v = Number(a[g.k]) || 0;
    if(g.min != null && v < g.min) return;
    if(g.max != null && v > g.max) return;
    g.ev.forEach((r, i) => {
      if(r[0] > age || r[1] < age) return;
      if(dbStageOf(r[0]) !== stage) return;
      out.push({t: r[3], e: r[4] || {}, w: r[2], lo: r[0], hi: r[1],
                id: 'ax' + gi + g.k + '_' + i, tags: [], aff: [g.k]});
    });
  });
  return out;
}
function chooseEv(stageName, age){
  const all = dbPool(stageName);
  if(!all || !all.length) return null;
  /* 前置通道 A：临终症状（剩余寿命 ≤ 4 年）
     最后 2 年（DYING_FORCE 以内）必定出症状 —— 死亡必须有直接征兆，不允许临死前还在写日常；
     3~4 年按 DYING_RATE(70%) 概率，留一点过日子的余味。 */
  const yl = yearsLeft();
  if(yl <= DYING_YEARS && (yl <= DYING_FORCE || Math.random() < DYING_RATE)){
    /* 优先挑没出现过的症状；全用过了才回落到最久远的一条（死亡铺垫不能省） */
    const dp = dyingPool(stageName, age);
    const d = pickNew(dp) || pickFresh(dp);
    if(d) return sigPick(d, dp);
  }
  /* 前置通道 B：属性专属（达到门槛才可能出现）
     用 pickNew 严格去重：本局已经出现过的属性事件不再重复；
     池子被抽干时直接放弃本通道、回落日常池，而不是硬抽老条目。 */
  if(Math.random() < ATTR_EV_RATE){
    const ap = attrPool(stageName, age);
    const a = pickNew(ap);
    if(a) return sigPick(a, ap);
  }
  /* once 事件抽过就不再出现 */
  const avail = all.filter(x => !(x.once && S && S.flags['ev_' + x.id]));
  const src = avail.length ? avail : all;
  const tiers = [];
  const inRange = src.filter(x => age >= x.lo && age <= x.hi);
  /* 需求 5：先按「事件属性 vs 我的属性」的差值挑最贴合的一条。
     差值 → 方差 → 纯随机 三级比较都在 pickByFit 里完成。
     注意只在「本局没出现过」的子集里挑，否则会盖掉 pickFresh 的先用新事件原则
     （池子耗尽前必须每条都用过一次，撞车只允许发生在池子抽干之后）。
     剩下的概率照旧走权重池，避免整局被同一类事件承包、也让内容更杂。 */
  const freshAvail = src.filter(x => !evStamp[x.t]);
  const fitBase = (freshAvail.length ? freshAvail
                  : (inRange.length ? inRange : src)).filter(x => evRecent.indexOf(x.t) < 0);
  const fit = pickByFit(fitBase);
  /* 需求：判定通道的权重从 0.75 降到 0.55 —— 留更多机会给下面的权重池 / LRU 兜底，
     同一阶段里的事件分布更散，不再是「永远那几条最贴合的」反复出现。 */
  if(fit && Math.random() < 0.55) return sigPick(fit, fitBase);
  if(inRange.length) tiers.push(inRange);
  tiers.push(src);
  for(let i = 0; i < tiers.length; i++){
    const r = pickFresh(tiers[i]);
    if(r) return sigPick(r, tiers[i]);
  }
  return sigPick(lruPick(all), all);
}
function localEvent(){
  const age = Math.round(S.age);
  const s = dbStageOf(age);
  // 时代专属事件：只从「青年」起才可能出现——幼年/童年/少年还没参与时代大事，
  // 否则会出现「3 岁在废墟里挖罐头」这种串插。
  if(age >= 19 && era.ev && era.ev.length && Math.random() < 0.35){
    const cands = era.ev.filter(x => !evStamp[x.t] && evRecent.indexOf(x.t) < 0);
    if(cands.length){
      const ee = pick(cands);
      markEv(ee.t);
      return {t: ee.t, e: ee.e, src:''};
    }
  }
  const e = chooseEv(s, age);
  if(!e) return {t:'你平静地过了一年。', e:{}, src:''};
  markEv(e.t);
  /* dying 也要透传：临终症状是「死亡铺垫」，日志与检测台都要能认出它 */
  return {t: e.t, e: e.e, src:'', tags: e.tags || [], aff: e.aff || null, dying: !!e.dying};
}
